//! Structured client for the optional Qiskit external runtime.
//!
//! The Python program below is platform-owned and receives only validated JSON.
//! It is not generated by the agent and cannot submit remote IBM Quantum jobs.

use crate::db::Database;
use crate::error::{AppError, AppResult};
use crate::models::quantum::{require_valid_circuit, QuantumCircuitSpec, QuantumSimulationRequest};
use crate::services::runtime_manager::{ControlledProcessRequest, RuntimeManager};
use base64::{engine::general_purpose::URL_SAFE_NO_PAD, Engine};
use serde_json::Value;
use std::path::PathBuf;
use std::time::Duration;

const QISKIT_RUNTIME_ID: &str = "external.qiskit";
const QISKIT_PLUGIN_ID: &str = "builtin-ibm-qiskit";
const QISKIT_WORKER: &str = r#"
import base64, json, sys
from qiskit import QuantumCircuit, transpile

payload = json.loads(base64.urlsafe_b64decode(sys.argv[2] + '=' * (-len(sys.argv[2]) % 4)))
action = sys.argv[1]
spec = payload['circuit']
qc = QuantumCircuit(spec['qubits'], spec.get('classicalBits', 0), name=spec['name'])
for op in spec.get('operations', []):
    gate = op['gate'].lower()
    qubits = op.get('qubits', [])
    params = op.get('parameters', [])
    if gate == 'measure':
        qc.measure(qubits[0], op['classicalBits'][0])
    elif gate == 'barrier':
        qc.barrier(*qubits)
    else:
        getattr(qc, gate)(*params, *qubits)

def summary(circuit):
    counts = {str(key): int(value) for key, value in circuit.count_ops().items()}
    return {
        'qubits': circuit.num_qubits,
        'classicalBits': circuit.num_clbits,
        'depth': circuit.depth() or 0,
        'size': circuit.size(),
        'operationCounts': counts,
        'twoQubitOperations': sum(value for key, value in counts.items() if key in ('cx', 'cz', 'swap', 'ecr')),
        'measurements': counts.get('measure', 0),
        'parameters': len(circuit.parameters),
    }

if action == 'analyze':
    result = {'analysis': summary(qc)}
elif action == 'transpile':
    output = transpile(qc, optimization_level=int(payload.get('optimizationLevel', 1)))
    result = {'original': summary(qc), 'transpiled': summary(output)}
elif action == 'simulate':
    from qiskit_aer import AerSimulator
    shots = int(payload['shots'])
    simulator = AerSimulator(seed_simulator=payload.get('seed'))
    compiled = transpile(qc, simulator)
    counts = simulator.run(compiled, shots=shots).result().get_counts(compiled)
    result = {'shots': shots, 'counts': {str(key): int(value) for key, value in counts.items()}, 'analysis': summary(compiled)}
else:
    raise ValueError('Unsupported Qiskit action')
print(json.dumps(result, separators=(',', ':')))
"#;

pub struct QiskitService;

/// Trusted, self-contained visualization template. It receives simulation data
/// only; its interaction code is owned by Bob Work and contains no model code
/// or external dependency/CDN.
pub fn render_interactive_circuit_html(circuit: &QuantumCircuitSpec, simulation: &Value) -> String {
    let counts = simulation
        .get("counts")
        .cloned()
        .unwrap_or_else(|| serde_json::json!({}));
    let zero = counts.get("00").and_then(Value::as_u64).unwrap_or(0);
    let one = counts.get("11").and_then(Value::as_u64).unwrap_or(0);
    let title = html_escape(&circuit.name);
    format!(
        r#"<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src 'unsafe-inline'; script-src 'unsafe-inline'; connect-src 'none'; img-src data:"><title>{title}</title><style>
:root{{font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;color:#101828;background:#f8fafc}}*{{box-sizing:border-box}}body{{margin:0;padding:18px}}h1{{font-size:18px;margin:0 0 4px}}p{{color:#475467;margin:0 0 14px}}.tabs{{display:flex;gap:8px;margin-bottom:14px}}button{{border:1px solid #cbd5e1;border-radius:9px;background:#fff;padding:8px 11px;font-weight:700;color:#344054}}button.active{{color:#fff;background:#0f62fe;border-color:#0f62fe}}.view{{display:none}}.view.active{{display:block}}.circuit{{border:1px solid #d0d5dd;border-radius:14px;background:#fff;padding:16px;overflow:auto}}.wire{{height:64px;border-bottom:2px solid #98a2b3;position:relative;min-width:460px}}.label{{position:absolute;left:0;top:20px;font-family:ui-monospace;font-weight:700}}.gate{{position:absolute;top:8px;width:45px;height:45px;display:grid;place-items:center;border-radius:9px;background:#155eef;color:#fff;font-weight:800;box-shadow:0 5px 12px #155eef44}}.gate.h{{left:115px}}.gate.cx{{left:245px}}.control{{position:absolute;left:261px;top:23px;width:13px;height:13px;border-radius:50%;background:#101828}}.link{{position:absolute;left:266px;top:-8px;height:55px;border-left:3px solid #101828}}.measure{{position:absolute;left:350px;background:#344054}}.hist{{display:flex;gap:20px;align-items:end;height:150px;padding:14px;border:1px solid #d0d5dd;border-radius:14px;background:#fff}}.bar{{width:92px;background:#0f62fe;border-radius:9px 9px 0 0;position:relative;min-height:8px}}.bar span{{position:absolute;bottom:-25px;width:100%;text-align:center;font-weight:800}}.bar i{{position:absolute;top:-24px;width:100%;text-align:center;font-style:normal;font-size:12px}}.scene-wrap{{height:310px;perspective:760px;border:1px solid #d0d5dd;border-radius:14px;background:radial-gradient(circle at 50% 30%,#e8f0ff,#101828);overflow:hidden;touch-action:none}}.scene{{height:100%;transform-style:preserve-3d;transform:rotateX(-16deg) rotateY(28deg);transition:transform .08s linear;position:relative}}.plane{{position:absolute;left:50%;top:50%;width:400px;height:210px;transform:translate(-50%,-50%) rotateX(68deg);border:2px solid #8ab4ff55;border-radius:18px;background:linear-gradient(90deg,#ffffff12 1px,transparent 1px),linear-gradient(#ffffff12 1px,transparent 1px);background-size:28px 28px}}.cube{{position:absolute;left:50%;top:50%;width:58px;height:58px;transform-style:preserve-3d;transform:translate(-50%,-50%) translate3d(var(--x),var(--y),var(--z))}}.cube b{{position:absolute;inset:0;background:var(--c);border:1px solid #fff9;border-radius:8px;display:grid;place-items:center;color:#fff;font-size:13px}}.cube b:nth-child(1){{transform:translateZ(29px)}}.cube b:nth-child(2){{transform:rotateY(90deg) translateZ(29px)}}.cube b:nth-child(3){{transform:rotateX(90deg) translateZ(29px)}}.hint{{margin-top:10px;font-size:12px;color:#667085}}@media(max-width:520px){{body{{padding:12px}}.scene-wrap{{height:270px}}}}
</style></head><body><h1>{title}</h1><p>Simulation locale Qiskit · sélectionnez une vue ou faites glisser la scène 3D.</p><div class="tabs"><button class="active" data-view="two">Circuit 2D</button><button data-view="three">Circuit 3D</button></div><section id="two" class="view active"><div class="circuit"><div class="wire"><span class="label">q₀</span><span class="gate h">H</span><span class="control"></span><span class="gate measure">M</span></div><div class="wire"><span class="label">q₁</span><span class="link"></span><span class="gate cx">X</span><span class="gate measure">M</span></div></div><div class="hist"><div class="bar" style="height:{zero_pct}%"><i>{zero}</i><span>00</span></div><div class="bar" style="height:{one_pct}%"><i>{one}</i><span>11</span></div></div></section><section id="three" class="view"><div class="scene-wrap" id="scene-wrap"><div class="scene" id="scene"><div class="plane"></div><div class="cube" style="--x:-110px;--y:-45px;--z:42px;--c:#155eef"><b>H</b><b>H</b><b>H</b></div><div class="cube" style="--x:15px;--y:-45px;--z:42px;--c:#101828"><b>●</b><b>●</b><b>●</b></div><div class="cube" style="--x:15px;--y:45px;--z:42px;--c:#0f62fe"><b>X</b><b>X</b><b>X</b></div><div class="cube" style="--x:130px;--y:-45px;--z:42px;--c:#344054"><b>M</b><b>M</b><b>M</b></div><div class="cube" style="--x:130px;--y:45px;--z:42px;--c:#344054"><b>M</b><b>M</b><b>M</b></div></div></div><div class="hint">Glissez pour tourner · pincez pour zoomer · double-cliquez pour réinitialiser.</div></section><script>const buttons=[...document.querySelectorAll('[data-view]')],views=[...document.querySelectorAll('.view')];buttons.forEach(b=>b.onclick=()=>{{buttons.forEach(x=>x.classList.toggle('active',x===b));views.forEach(v=>v.classList.toggle('active',v.id===b.dataset.view))}});const w=document.getElementById('scene-wrap'),s=document.getElementById('scene');let x=-16,y=28,z=1,start,pinch;function paint(){{s.style.transform=`rotateX(${{x}}deg) rotateY(${{y}}deg) scale(${{z}})`}}function distance(t){{return Math.hypot(t[0].clientX-t[1].clientX,t[0].clientY-t[1].clientY)}}w.onpointerdown=e=>{{start=[e.clientX,e.clientY];w.setPointerCapture(e.pointerId)}};w.onpointermove=e=>{{if(!start)return;y+=(e.clientX-start[0])*.45;x-=(e.clientY-start[1])*.45;start=[e.clientX,e.clientY];paint()}};w.onpointerup=()=>start=null;w.onwheel=e=>{{e.preventDefault();z=Math.max(.65,Math.min(1.6,z-e.deltaY*.001));paint()}};w.addEventListener('touchstart',e=>{{if(e.touches.length===2)pinch=distance(e.touches)}},{{passive:false}});w.addEventListener('touchmove',e=>{{if(e.touches.length!==2||!pinch)return;e.preventDefault();const next=distance(e.touches);z=Math.max(.65,Math.min(1.6,z*next/pinch));pinch=next;paint()}},{{passive:false}});w.addEventListener('touchend',()=>pinch=null);w.ondblclick=()=>{{x=-16;y=28;z=1;paint()}};</script></body></html>"#,
        zero_pct = (zero as f64 / (zero + one).max(1) as f64 * 100.0),
        one_pct = (one as f64 / (zero + one).max(1) as f64 * 100.0)
    )
}

fn html_escape(value: &str) -> String {
    value
        .replace('&', "&amp;")
        .replace('<', "&lt;")
        .replace('>', "&gt;")
        .replace('"', "&quot;")
        .replace('\'', "&#39;")
}

impl QiskitService {
    pub fn new() -> Self {
        Self
    }

    pub async fn analyze(
        &self,
        db: &Database,
        manager: &RuntimeManager,
        manifest: &Value,
        circuit: QuantumCircuitSpec,
    ) -> AppResult<Value> {
        require_valid_circuit(&circuit)?;
        self.execute(
            db,
            manager,
            manifest,
            "analyze",
            serde_json::json!({"circuit": circuit}),
        )
        .await
    }

    pub async fn transpile(
        &self,
        db: &Database,
        manager: &RuntimeManager,
        manifest: &Value,
        circuit: QuantumCircuitSpec,
        optimization_level: u8,
    ) -> AppResult<Value> {
        require_valid_circuit(&circuit)?;
        if optimization_level > 3 {
            return Err(AppError::ValidationFailed(
                "Qiskit optimization level must be between 0 and 3".into(),
            ));
        }
        self.execute(
            db,
            manager,
            manifest,
            "transpile",
            serde_json::json!({"circuit": circuit, "optimizationLevel": optimization_level}),
        )
        .await
    }

    pub async fn simulate(
        &self,
        db: &Database,
        manager: &RuntimeManager,
        manifest: &Value,
        request: QuantumSimulationRequest,
    ) -> AppResult<Value> {
        require_valid_circuit(&request.circuit)?;
        if request.shots == 0 || request.shots > 1_000_000 {
            return Err(AppError::ValidationFailed(
                "Simulation shots must be between 1 and 1,000,000".into(),
            ));
        }
        self.execute(
            db,
            manager,
            manifest,
            "simulate",
            serde_json::json!({
                "circuit": request.circuit, "shots": request.shots, "seed": request.seed,
            }),
        )
        .await
    }

    async fn execute(
        &self,
        db: &Database,
        manager: &RuntimeManager,
        manifest: &Value,
        action: &str,
        payload: Value,
    ) -> AppResult<Value> {
        let handle =
            manager.resolve_external_runtime(db, QISKIT_PLUGIN_ID, manifest, QISKIT_RUNTIME_ID)?;
        let executable = handle.executable.map(PathBuf::from).ok_or_else(|| {
            AppError::NotFound("Qiskit Runtime did not provide a Python interpreter".into())
        })?;
        let working_directory = handle
            .working_root
            .map(PathBuf::from)
            .ok_or_else(|| AppError::NotFound("Qiskit Runtime working directory".into()))?;
        let encoded = URL_SAFE_NO_PAD.encode(serde_json::to_vec(&payload)?);
        let output = manager
            .execute_controlled(
                manifest,
                ControlledProcessRequest {
                    plugin_id: QISKIT_PLUGIN_ID.into(),
                    runtime_id: QISKIT_RUNTIME_ID.into(),
                    executable,
                    args: vec!["-c".into(), QISKIT_WORKER.into(), action.into(), encoded],
                    working_directory,
                    environment: handle.environment,
                    timeout: Duration::from_secs(120),
                },
            )
            .await?;
        if output.timed_out || output.cancelled || output.exit_code != Some(0) {
            return Err(AppError::Io(format!(
                "Qiskit {} failed: {}",
                action,
                output.stderr.trim()
            )));
        }
        serde_json::from_str(output.stdout.trim()).map_err(|error| {
            AppError::ValidationFailed(format!(
                "Qiskit returned invalid structured output: {error}"
            ))
        })
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::models::quantum::QuantumOperation;

    #[test]
    fn worker_is_static_and_never_contains_ibm_service_submission() {
        assert!(QISKIT_WORKER.contains("AerSimulator"));
        assert!(!QISKIT_WORKER.contains("QiskitRuntimeService"));
    }

    #[test]
    fn structured_payload_is_bounded_before_runtime_execution() {
        let circuit = QuantumCircuitSpec {
            name: "Bell".into(),
            qubits: 2,
            classical_bits: 2,
            operations: vec![QuantumOperation {
                id: "h".into(),
                gate: "h".into(),
                qubits: vec![0],
                classical_bits: vec![],
                parameters: vec![],
            }],
        };
        assert!(require_valid_circuit(&circuit).is_ok());
    }

    #[test]
    fn interactive_visualization_is_self_contained_and_has_2d_and_3d_views() {
        let circuit = QuantumCircuitSpec {
            name: "Bell".into(),
            qubits: 2,
            classical_bits: 2,
            operations: vec![],
        };
        let html = render_interactive_circuit_html(
            &circuit,
            &serde_json::json!({"counts":{"00":2087,"11":2009}}),
        );
        assert!(html.contains("Circuit 2D"));
        assert!(html.contains("Circuit 3D"));
        assert!(html.contains("Content-Security-Policy"));
        assert!(html.contains("onpointermove"));
        assert!(html.contains("touchmove"));
        assert!(html.contains("onwheel"));
        assert!(!html.contains("https://"));
    }
}
